	/**
	 * Default Constructor
	 */
    public ThirdPartyService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ThirdPartyEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ThirdPartyRepository.class) );
		this.validator		= applicationContext.getBean(ThirdPartyValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ThirdParty
	 */
		public ThirdParty createThirdParty( CreateThirdPartyCommand command ) {

		ThirdParty entity = new ThirdParty();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setThirdPartyId( command.getThirdPartyId() );
            entity.setName( command.getName() );
            entity.setCountry( command.getCountry() );
            entity.setContactEmail( command.getContactEmail() );
            entity.setThirdPartyType( command.getThirdPartyType() );
            entity.setCriticality( command.getCriticality() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ThirdParty {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateThirdPartyCommand
	 * @return		ThirdParty
	 */
	public ThirdParty updateThirdParty( UpdateThirdPartyCommand command ) {

		ThirdParty entity = new ThirdParty();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setThirdPartyId( command.getThirdPartyId() );
            entity.setName( command.getName() );
            entity.setCountry( command.getCountry() );
            entity.setContactEmail( command.getContactEmail() );
            entity.setOrganization( command.getOrganization() );
            entity.setProcessingActivities( command.getProcessingActivities() );
            entity.setAssessments( command.getAssessments() );
            entity.setContracts( command.getContracts() );
            entity.setObligations( command.getObligations() );
            entity.setDataBreaches( command.getDataBreaches() );
            entity.setThirdPartyType( command.getThirdPartyType() );
            entity.setCriticality( command.getCriticality() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ThirdParty {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteThirdPartyCommand
	 */
	public void delete( DeleteThirdPartyCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getThirdPartyId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of ThirdParty {0} ", id );

	}

	/**
	 * Method to retrieve the ThirdParty via ThirdPartyFetchOneSummary
	 * @param 	summary ThirdPartyFetchOneSummary
	 * @return 	ThirdPartyFetchOneResponse
	 */
	public ThirdParty getThirdParty( ThirdPartyFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ThirdPartyFetchOneSummary arg cannot be null" );

		ThirdParty entity = null;
		UUID id = summary.getThirdPartyId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ThirdParty using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all ThirdPartys
	 *
	 * @return 	List<ThirdParty>
	 */
    public List<ThirdParty> getAllThirdParty() {
		List<ThirdParty> list = projector.findAll( new FindAllThirdPartyQuery() );
		return list;
	}

	/**
	 * assign Organization on ThirdParty
	 * @param		command AssignOrganizationToThirdPartyCommand
	 */
	public void assignOrganization( AssignOrganizationToThirdPartyCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getThirdPartyId(), command.getAssignment());

	}

